/* cpp-L2.js — CPP Lesson 2 content (EN + TR) */
var CPP_L2 = {
en: "<p class=\"l-text\">Object-Oriented Programming (OOP) is a paradigm where you organize code around <strong>objects</strong> — bundles of data (attributes) and functions that operate on that data (methods). Instead of having loose functions and separate data structures like in C, you put them together in a <strong>class</strong>.</p><div class=\"lesson-outcomes\" style=\"background:rgba(200,169,110,0.06);border-left:3px solid #c8a96e;padding:1rem 1.2rem;margin:1.5rem 0;border-radius:0 8px 8px 0\"><div style=\"font-size:0.78rem;font-weight:700;letter-spacing:0.08em;color:#c8a96e;margin-bottom:0.6rem\">📍 WHAT YOU'LL LEARN</div><ul style=\"margin:0;padding-left:1.3rem;line-height:1.65;font-size:0.93rem;color:rgba(235,230,220,0.92)\"><li>Define classes with constructors, destructors, and access modifiers</li><li>Apply RAII to tie resource lifetime to object lifetime safely</li><li>Implement copy and move constructors for proper value semantics</li><li>Use the rule of zero, three, and five to manage resource ownership</li><li>Distinguish stack-allocated and heap-allocated objects</li></ul></div><div class=\"l-highlight\"><strong>Why OOP?</strong> Think about modeling a bank account in C: you would have a <code>struct</code> for the data (balance, owner) and separate functions (<code>deposit()</code>, <code>withdraw()</code>) that take the struct as a parameter. Nothing prevents someone from directly modifying <code>account.balance</code> to a negative number. OOP solves this: the class <strong>encapsulates</strong> the data, making <code>balance</code> private and only allowing changes through controlled methods that enforce rules (like \"balance cannot go negative\").</div><p class=\"l-text\"><strong>Procedural vs OOP</strong> — let's see the difference with a concrete example:</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> procedural_vs_oop.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string&gt;</span>\n\n<span class=\"cm\">// ===== PROCEDURAL APPROACH =====</span>\n<span class=\"kw\">struct</span> <span class=\"ty\">AccountData</span> {\n    <span class=\"ty\">std::string</span> owner;\n    <span class=\"ty\">double</span> balance;\n};\n\n<span class=\"ty\">void</span> <span class=\"fn\">deposit_proc</span>(<span class=\"ty\">AccountData</span>&amp; acc, <span class=\"ty\">double</span> amount) {\n    acc.balance += amount;  <span class=\"cm\">// no validation!</span>\n}\n\n<span class=\"cm\">// ===== OOP APPROACH =====</span>\n<span class=\"kw\">class</span> <span class=\"ty\">Account</span> {\n<span class=\"kw\">private</span>:\n    <span class=\"ty\">std::string</span> owner_;\n    <span class=\"ty\">double</span> balance_;\n\n<span class=\"kw\">public</span>:\n    <span class=\"ty\">Account</span>(<span class=\"kw\">const</span> <span class=\"ty\">std::string</span>&amp; owner, <span class=\"ty\">double</span> initial)\n        : owner_(owner), balance_(initial) {}\n\n    <span class=\"ty\">bool</span> <span class=\"fn\">deposit</span>(<span class=\"ty\">double</span> amount) {\n        <span class=\"kw\">if</span> (amount &lt;= <span class=\"num\">0</span>) <span class=\"kw\">return</span> <span class=\"kw\">false</span>;  <span class=\"cm\">// validation!</span>\n        balance_ += amount;\n        <span class=\"kw\">return</span> <span class=\"kw\">true</span>;\n    }\n\n    <span class=\"ty\">double</span> <span class=\"fn\">get_balance</span>() <span class=\"kw\">const</span> { <span class=\"kw\">return</span> balance_; }\n    <span class=\"ty\">std::string</span> <span class=\"fn\">get_owner</span>() <span class=\"kw\">const</span> { <span class=\"kw\">return</span> owner_; }\n};\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"cm\">// Procedural: anyone can break invariants</span>\n    <span class=\"ty\">AccountData</span> a1 = {<span class=\"str\">\"Begüm\"</span>, <span class=\"num\">1000.0</span>};\n    a1.balance = <span class=\"num\">-999</span>;  <span class=\"cm\">// oops! no protection</span>\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"Procedural: \"</span> &lt;&lt; a1.balance &lt;&lt; <span class=\"str\">'\\n'</span>;\n\n    <span class=\"cm\">// OOP: data is protected</span>\n    <span class=\"ty\">Account</span> a2(<span class=\"str\">\"Mikail\"</span>, <span class=\"num\">1000.0</span>);\n    <span class=\"cm\">// a2.balance_ = -999;  // COMPILE ERROR: private!</span>\n    a2.<span class=\"fn\">deposit</span>(<span class=\"num\">500</span>);\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"OOP: \"</span> &lt;&lt; a2.<span class=\"fn\">get_owner</span>() &lt;&lt; <span class=\"str\">\" has $\"</span> &lt;&lt; a2.<span class=\"fn\">get_balance</span>() &lt;&lt; <span class=\"str\">'\\n'</span>;\n\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>Procedural: -999\nOOP: Mikail has $1500</code></pre></div></div><p class=\"l-text\"><strong>Access modifiers</strong> control who can access what:</p><ul class=\"l-list\"><li><code>private</code> — only accessible inside the class itself. This is the default for classes. Use for internal state that should not be modified directly.</li><li><code>public</code> — accessible from anywhere. Use for the interface — the methods you want users to call.</li><li><code>protected</code> — accessible inside the class and its derived classes (subclasses). Use when inheritance needs access to base class internals.</li></ul><p class=\"l-text\"><strong>Constructors and Destructors</strong> — A constructor is a special function called automatically when an object is created. It initializes the object's state. A destructor is called automatically when the object is destroyed (goes out of scope). This is the foundation of <strong>RAII</strong>: acquire resources in the constructor, release them in the destructor.</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> lifecycle.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string&gt;</span>\n\n<span class=\"kw\">class</span> <span class=\"ty\">Resource</span> {\n<span class=\"kw\">private</span>:\n    <span class=\"ty\">std::string</span> name_;\n\n<span class=\"kw\">public</span>:\n    <span class=\"cm\">// Default constructor</span>\n    <span class=\"ty\">Resource</span>() : name_(<span class=\"str\">\"unnamed\"</span>) {\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  Default constructor: \"</span> &lt;&lt; name_ &lt;&lt; <span class=\"str\">'\\n'</span>;\n    }\n\n    <span class=\"cm\">// Parameterized constructor</span>\n    <span class=\"ty\">Resource</span>(<span class=\"kw\">const</span> <span class=\"ty\">std::string</span>&amp; name) : name_(name) {\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  Parameterized constructor: \"</span> &lt;&lt; name_ &lt;&lt; <span class=\"str\">'\\n'</span>;\n    }\n\n    <span class=\"cm\">// Destructor — called automatically when object goes out of scope</span>\n    ~<span class=\"ty\">Resource</span>() {\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  Destructor: \"</span> &lt;&lt; name_ &lt;&lt; <span class=\"str\">'\\n'</span>;\n    }\n\n    <span class=\"ty\">std::string</span> <span class=\"fn\">name</span>() <span class=\"kw\">const</span> { <span class=\"kw\">return</span> name_; }\n};\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- Creating objects ---\\n\"</span>;\n    <span class=\"ty\">Resource</span> r1;               <span class=\"cm\">// calls default constructor</span>\n    <span class=\"ty\">Resource</span> r2(<span class=\"str\">\"FileHandle\"</span>);  <span class=\"cm\">// calls parameterized constructor</span>\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- Entering scope ---\\n\"</span>;\n    {\n        <span class=\"ty\">Resource</span> r3(<span class=\"str\">\"TempBuffer\"</span>);\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  Using \"</span> &lt;&lt; r3.<span class=\"fn\">name</span>() &lt;&lt; <span class=\"str\">'\\n'</span>;\n    }  <span class=\"cm\">// r3 destroyed here!</span>\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- Exiting main ---\\n\"</span>;\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}  <span class=\"cm\">// r2 destroyed, then r1 (reverse order!)</span></code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>--- Creating objects ---\n  Default constructor: unnamed\n  Parameterized constructor: FileHandle\n--- Entering scope ---\n  Parameterized constructor: TempBuffer\n  Using TempBuffer\n  Destructor: TempBuffer\n--- Exiting main ---\n  Destructor: FileHandle\n  Destructor: unnamed</code></pre></div></div><div class=\"l-note\"><strong>Tip:</strong> Objects are destroyed in <strong>reverse order</strong> of construction. This ensures that if object B depends on object A (created first), A is still alive when B is being destroyed.</div><p class=\"l-text\"><strong>Member initializer lists</strong> — always prefer initializing members in the initializer list (after the <code>:</code>) rather than assigning inside the constructor body. For <code>const</code> members, references, and base classes, it is the <strong>only</strong> option. For other members, it is more efficient (direct initialization vs default-construction-then-assignment).</p><p class=\"l-text\"><strong>The <code>this</code> pointer</strong> — inside any member function, <code>this</code> is a pointer to the current object. It is useful for resolving name ambiguity and for <strong>method chaining</strong>:</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> chaining.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string&gt;</span>\n\n<span class=\"kw\">class</span> <span class=\"ty\">QueryBuilder</span> {\n<span class=\"kw\">private</span>:\n    <span class=\"ty\">std::string</span> table_;\n    <span class=\"ty\">std::string</span> condition_;\n    <span class=\"ty\">int</span> limit_;\n\n<span class=\"kw\">public</span>:\n    <span class=\"ty\">QueryBuilder</span>() : limit_(<span class=\"num\">0</span>) {}\n\n    <span class=\"cm\">// Each method returns *this for chaining</span>\n    <span class=\"ty\">QueryBuilder</span>&amp; <span class=\"fn\">from</span>(<span class=\"kw\">const</span> <span class=\"ty\">std::string</span>&amp; table) {\n        table_ = table;\n        <span class=\"kw\">return</span> *<span class=\"kw\">this</span>;\n    }\n    <span class=\"ty\">QueryBuilder</span>&amp; <span class=\"fn\">where</span>(<span class=\"kw\">const</span> <span class=\"ty\">std::string</span>&amp; cond) {\n        condition_ = cond;\n        <span class=\"kw\">return</span> *<span class=\"kw\">this</span>;\n    }\n    <span class=\"ty\">QueryBuilder</span>&amp; <span class=\"fn\">limit</span>(<span class=\"ty\">int</span> n) {\n        limit_ = n;\n        <span class=\"kw\">return</span> *<span class=\"kw\">this</span>;\n    }\n    <span class=\"ty\">std::string</span> <span class=\"fn\">build</span>() <span class=\"kw\">const</span> {\n        <span class=\"ty\">std::string</span> q = <span class=\"str\">\"SELECT * FROM \"</span> + table_;\n        <span class=\"kw\">if</span> (!condition_.<span class=\"fn\">empty</span>()) q += <span class=\"str\">\" WHERE \"</span> + condition_;\n        <span class=\"kw\">if</span> (limit_ &gt; <span class=\"num\">0</span>) q += <span class=\"str\">\" LIMIT \"</span> + <span class=\"fn\">std::to_string</span>(limit_);\n        <span class=\"kw\">return</span> q;\n    }\n};\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"ty\">std::string</span> query = <span class=\"ty\">QueryBuilder</span>()\n        .<span class=\"fn\">from</span>(<span class=\"str\">\"users\"</span>)\n        .<span class=\"fn\">where</span>(<span class=\"str\">\"age > 18\"</span>)\n        .<span class=\"fn\">limit</span>(<span class=\"num\">10</span>)\n        .<span class=\"fn\">build</span>();\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; query &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>SELECT * FROM users WHERE age > 18 LIMIT 10</code></pre></div></div><p class=\"l-text\"><strong>Operator overloading</strong> — C++ lets you define how operators (<code>+</code>, <code>-</code>, <code>==</code>, <code>&lt;&lt;</code>, etc.) work with your custom types. This makes user-defined types feel like built-in types:</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> vec2.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;cmath&gt;</span>\n\n<span class=\"kw\">class</span> <span class=\"ty\">Vec2</span> {\n<span class=\"kw\">public</span>:\n    <span class=\"ty\">double</span> x, y;\n\n    <span class=\"ty\">Vec2</span>(<span class=\"ty\">double</span> x = <span class=\"num\">0</span>, <span class=\"ty\">double</span> y = <span class=\"num\">0</span>) : x(x), y(y) {}\n\n    <span class=\"cm\">// Arithmetic operators</span>\n    <span class=\"ty\">Vec2</span> <span class=\"kw\">operator</span>+(<span class=\"kw\">const</span> <span class=\"ty\">Vec2</span>&amp; o) <span class=\"kw\">const</span> { <span class=\"kw\">return</span> {x + o.x, y + o.y}; }\n    <span class=\"ty\">Vec2</span> <span class=\"kw\">operator</span>-(<span class=\"kw\">const</span> <span class=\"ty\">Vec2</span>&amp; o) <span class=\"kw\">const</span> { <span class=\"kw\">return</span> {x - o.x, y - o.y}; }\n    <span class=\"ty\">Vec2</span> <span class=\"kw\">operator</span>*(<span class=\"ty\">double</span> s)       <span class=\"kw\">const</span> { <span class=\"kw\">return</span> {x * s, y * s}; }\n\n    <span class=\"cm\">// Comparison</span>\n    <span class=\"ty\">bool</span> <span class=\"kw\">operator</span>==(<span class=\"kw\">const</span> <span class=\"ty\">Vec2</span>&amp; o) <span class=\"kw\">const</span> { <span class=\"kw\">return</span> x == o.x &amp;&amp; y == o.y; }\n\n    <span class=\"cm\">// Length</span>\n    <span class=\"ty\">double</span> <span class=\"fn\">length</span>() <span class=\"kw\">const</span> { <span class=\"kw\">return</span> <span class=\"fn\">std::sqrt</span>(x * x + y * y); }\n\n    <span class=\"cm\">// Stream output operator (friend function)</span>\n    <span class=\"kw\">friend</span> <span class=\"ty\">std::ostream</span>&amp; <span class=\"kw\">operator</span>&lt;&lt;(<span class=\"ty\">std::ostream</span>&amp; os, <span class=\"kw\">const</span> <span class=\"ty\">Vec2</span>&amp; v) {\n        os &lt;&lt; <span class=\"str\">\"(\"</span> &lt;&lt; v.x &lt;&lt; <span class=\"str\">\", \"</span> &lt;&lt; v.y &lt;&lt; <span class=\"str\">\")\"</span>;\n        <span class=\"kw\">return</span> os;\n    }\n};\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"ty\">Vec2</span> a(<span class=\"num\">3</span>, <span class=\"num\">4</span>), b(<span class=\"num\">1</span>, <span class=\"num\">2</span>);\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"a = \"</span> &lt;&lt; a &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"b = \"</span> &lt;&lt; b &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"a + b = \"</span> &lt;&lt; (a + b) &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"a - b = \"</span> &lt;&lt; (a - b) &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"a * 2 = \"</span> &lt;&lt; (a * <span class=\"num\">2</span>) &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"|a| = \"</span> &lt;&lt; a.<span class=\"fn\">length</span>() &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"a == b? \"</span> &lt;&lt; (a == b ? <span class=\"str\">\"yes\"</span> : <span class=\"str\">\"no\"</span>) &lt;&lt; <span class=\"str\">'\\n'</span>;\n\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>a = (3, 4)\nb = (1, 2)\na + b = (4, 6)\na - b = (2, 2)\na * 2 = (6, 8)\n|a| = 5\na == b? no</code></pre></div></div><div class=\"l-highlight\"><strong>The Rule of Three</strong> — If your class manages a resource (heap memory, file handle, network socket), you must define three things: (1) a <strong>destructor</strong> to release it, (2) a <strong>copy constructor</strong> to deep-copy it, and (3) a <strong>copy assignment operator</strong> to handle <code>a = b</code>. If you define one, you almost certainly need all three.</div><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> rule_of_three.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;cstring&gt;</span>\n\n<span class=\"kw\">class</span> <span class=\"ty\">DynString</span> {\n<span class=\"kw\">private</span>:\n    <span class=\"ty\">char</span>* data_;\n    <span class=\"ty\">size_t</span> len_;\n\n<span class=\"kw\">public</span>:\n    <span class=\"cm\">// Constructor</span>\n    <span class=\"ty\">DynString</span>(<span class=\"kw\">const</span> <span class=\"ty\">char</span>* s = <span class=\"str\">\"\"</span>) {\n        len_ = <span class=\"fn\">std::strlen</span>(s);\n        data_ = <span class=\"kw\">new</span> <span class=\"ty\">char</span>[len_ + <span class=\"num\">1</span>];\n        <span class=\"fn\">std::strcpy</span>(data_, s);\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  Construct: \\\"\"</span> &lt;&lt; data_ &lt;&lt; <span class=\"str\">\"\\\"\"</span> &lt;&lt; <span class=\"str\">'\\n'</span>;\n    }\n\n    <span class=\"cm\">// Destructor</span>\n    ~<span class=\"ty\">DynString</span>() {\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  Destruct: \\\"\"</span> &lt;&lt; data_ &lt;&lt; <span class=\"str\">\"\\\"\"</span> &lt;&lt; <span class=\"str\">'\\n'</span>;\n        <span class=\"kw\">delete</span>[] data_;\n    }\n\n    <span class=\"cm\">// Copy constructor (deep copy)</span>\n    <span class=\"ty\">DynString</span>(<span class=\"kw\">const</span> <span class=\"ty\">DynString</span>&amp; other) {\n        len_ = other.len_;\n        data_ = <span class=\"kw\">new</span> <span class=\"ty\">char</span>[len_ + <span class=\"num\">1</span>];\n        <span class=\"fn\">std::strcpy</span>(data_, other.data_);\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  Copy: \\\"\"</span> &lt;&lt; data_ &lt;&lt; <span class=\"str\">\"\\\"\"</span> &lt;&lt; <span class=\"str\">'\\n'</span>;\n    }\n\n    <span class=\"cm\">// Copy assignment operator</span>\n    <span class=\"ty\">DynString</span>&amp; <span class=\"kw\">operator</span>=(<span class=\"kw\">const</span> <span class=\"ty\">DynString</span>&amp; other) {\n        <span class=\"kw\">if</span> (<span class=\"kw\">this</span> != &amp;other) {  <span class=\"cm\">// self-assignment check</span>\n            <span class=\"kw\">delete</span>[] data_;\n            len_ = other.len_;\n            data_ = <span class=\"kw\">new</span> <span class=\"ty\">char</span>[len_ + <span class=\"num\">1</span>];\n            <span class=\"fn\">std::strcpy</span>(data_, other.data_);\n            <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  Assign: \\\"\"</span> &lt;&lt; data_ &lt;&lt; <span class=\"str\">\"\\\"\"</span> &lt;&lt; <span class=\"str\">'\\n'</span>;\n        }\n        <span class=\"kw\">return</span> *<span class=\"kw\">this</span>;\n    }\n\n    <span class=\"kw\">const</span> <span class=\"ty\">char</span>* <span class=\"fn\">c_str</span>() <span class=\"kw\">const</span> { <span class=\"kw\">return</span> data_; }\n};\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- Construction ---\\n\"</span>;\n    <span class=\"ty\">DynString</span> s1(<span class=\"str\">\"Hello\"</span>);\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- Copy construction ---\\n\"</span>;\n    <span class=\"ty\">DynString</span> s2 = s1;  <span class=\"cm\">// calls copy constructor</span>\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- Assignment ---\\n\"</span>;\n    <span class=\"ty\">DynString</span> s3(<span class=\"str\">\"World\"</span>);\n    s3 = s1;            <span class=\"cm\">// calls copy assignment operator</span>\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- Destruction (reverse order) ---\\n\"</span>;\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>--- Construction ---\n  Construct: \"Hello\"\n--- Copy construction ---\n  Copy: \"Hello\"\n--- Assignment ---\n  Construct: \"World\"\n  Assign: \"Hello\"\n--- Destruction (reverse order) ---\n  Destruct: \"Hello\"\n  Destruct: \"Hello\"\n  Destruct: \"Hello\"</code></pre></div></div><div class=\"l-warn\"><strong>Warning:</strong> Without a proper copy constructor, the compiler generates a <strong>shallow copy</strong> — it copies the pointer, not the data. Then both objects point to the same memory. When the first one is destroyed, it frees the memory. The second object now has a dangling pointer — use-after-free, double-free, crash.</div><p class=\"l-text\"><strong>Static members</strong> — belong to the class itself, not to any particular object. A <code>static</code> data member is shared across all instances, and a <code>static</code> method can be called without an object:</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> static_demo.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n\n<span class=\"kw\">class</span> <span class=\"ty\">Entity</span> {\n<span class=\"kw\">private</span>:\n    <span class=\"kw\">static</span> <span class=\"ty\">int</span> count_;  <span class=\"cm\">// shared across ALL instances</span>\n    <span class=\"ty\">int</span> id_;\n\n<span class=\"kw\">public</span>:\n    <span class=\"ty\">Entity</span>() : id_(++count_) {\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"Entity #\"</span> &lt;&lt; id_ &lt;&lt; <span class=\"str\">\" created (total: \"</span> &lt;&lt; count_ &lt;&lt; <span class=\"str\">\")\\n\"</span>;\n    }\n    ~<span class=\"ty\">Entity</span>() {\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"Entity #\"</span> &lt;&lt; id_ &lt;&lt; <span class=\"str\">\" destroyed\\n\"</span>;\n        --count_;\n    }\n    <span class=\"kw\">static</span> <span class=\"ty\">int</span> <span class=\"fn\">total</span>() { <span class=\"kw\">return</span> count_; }\n};\n\n<span class=\"ty\">int</span> <span class=\"ty\">Entity</span>::count_ = <span class=\"num\">0</span>;  <span class=\"cm\">// define static member outside class</span>\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"ty\">Entity</span> a, b;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"Total: \"</span> &lt;&lt; <span class=\"ty\">Entity</span>::<span class=\"fn\">total</span>() &lt;&lt; <span class=\"str\">'\\n'</span>;\n    {\n        <span class=\"ty\">Entity</span> c;\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"Total: \"</span> &lt;&lt; <span class=\"ty\">Entity</span>::<span class=\"fn\">total</span>() &lt;&lt; <span class=\"str\">'\\n'</span>;\n    }\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"Total: \"</span> &lt;&lt; <span class=\"ty\">Entity</span>::<span class=\"fn\">total</span>() &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>Entity #1 created (total: 1)\nEntity #2 created (total: 2)\nTotal: 2\nEntity #3 created (total: 3)\nTotal: 3\nEntity #3 destroyed\nTotal: 2\nEntity #2 destroyed\nEntity #1 destroyed</code></pre></div></div><p class=\"l-text\"><strong>Move Constructor (C++11)</strong> — copying is expensive when the source is about to die anyway. For a function that returns a <code>DynString</code>, or a vector that has to grow, why allocate a new buffer and memcpy the bytes when you could just <em>steal</em> the pointer from the old object? That is the job of the <strong>move constructor</strong>. It takes an <code>rvalue reference</code> (<code>T&amp;&amp;</code>) — a reference that binds only to temporaries (or to things you explicitly mark with <code>std::move</code>) — and transfers ownership of the internals.</p><div class=\"l-highlight\"><strong>Rvalue references in one minute.</strong> An <em>lvalue</em> is something with a name and an address you can take (<code>int x; x = 5;</code>). An <em>rvalue</em> is a temporary, like the result of <code>x + 1</code> or a function return value. <code>T&amp;</code> binds to lvalues, <code>const T&amp;</code> binds to both. <code>T&amp;&amp;</code> binds only to rvalues — which means you know the source is about to be destroyed, so it is safe to gut it.</div><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> move_ctor.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;cstring&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;utility&gt;</span>  <span class=\"cm\">// std::move</span>\n\n<span class=\"kw\">class</span> <span class=\"ty\">DynString</span> {\n<span class=\"kw\">private</span>:\n    <span class=\"ty\">char</span>* data_;\n    <span class=\"ty\">size_t</span> len_;\n\n<span class=\"kw\">public</span>:\n    <span class=\"ty\">DynString</span>(<span class=\"kw\">const</span> <span class=\"ty\">char</span>* s = <span class=\"str\">\"\"</span>) : len_(<span class=\"fn\">std::strlen</span>(s)) {\n        data_ = <span class=\"kw\">new</span> <span class=\"ty\">char</span>[len_ + <span class=\"num\">1</span>];\n        <span class=\"fn\">std::strcpy</span>(data_, s);\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  ctor      \\\"\"</span> &lt;&lt; data_ &lt;&lt; <span class=\"str\">\"\\\"\\n\"</span>;\n    }\n    ~<span class=\"ty\">DynString</span>() {\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  dtor      \"</span> &lt;&lt; (data_ ? data_ : <span class=\"str\">\"(moved-from)\"</span>) &lt;&lt; <span class=\"str\">'\\n'</span>;\n        <span class=\"kw\">delete</span>[] data_;\n    }\n\n    <span class=\"cm\">// Copy constructor — allocates and copies bytes (expensive)</span>\n    <span class=\"ty\">DynString</span>(<span class=\"kw\">const</span> <span class=\"ty\">DynString</span>&amp; other) : len_(other.len_) {\n        data_ = <span class=\"kw\">new</span> <span class=\"ty\">char</span>[len_ + <span class=\"num\">1</span>];\n        <span class=\"fn\">std::strcpy</span>(data_, other.data_);\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  copy ctor \\\"\"</span> &lt;&lt; data_ &lt;&lt; <span class=\"str\">\"\\\" (deep copy)\\n\"</span>;\n    }\n\n    <span class=\"cm\">// Move constructor — steals the pointer (cheap, O(1))</span>\n    <span class=\"ty\">DynString</span>(<span class=\"ty\">DynString</span>&amp;&amp; other) <span class=\"kw\">noexcept</span>\n        : data_(other.data_), len_(other.len_) {\n        other.data_ = <span class=\"kw\">nullptr</span>;  <span class=\"cm\">// leave source in a valid, destructible state</span>\n        other.len_  = <span class=\"num\">0</span>;\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  move ctor \\\"\"</span> &lt;&lt; data_ &lt;&lt; <span class=\"str\">\"\\\" (stole pointer)\\n\"</span>;\n    }\n\n    <span class=\"cm\">// Move assignment — release ours, steal theirs</span>\n    <span class=\"ty\">DynString</span>&amp; <span class=\"kw\">operator</span>=(<span class=\"ty\">DynString</span>&amp;&amp; other) <span class=\"kw\">noexcept</span> {\n        <span class=\"kw\">if</span> (<span class=\"kw\">this</span> != &amp;other) {\n            <span class=\"kw\">delete</span>[] data_;\n            data_ = other.data_;\n            len_  = other.len_;\n            other.data_ = <span class=\"kw\">nullptr</span>;\n            other.len_  = <span class=\"num\">0</span>;\n            <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  move=     (stole pointer)\\n\"</span>;\n        }\n        <span class=\"kw\">return</span> *<span class=\"kw\">this</span>;\n    }\n};\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- copy from lvalue ---\\n\"</span>;\n    <span class=\"ty\">DynString</span> a(<span class=\"str\">\"Hello\"</span>);\n    <span class=\"ty\">DynString</span> b = a;             <span class=\"cm\">// copy ctor (a is an lvalue)</span>\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- move from rvalue ---\\n\"</span>;\n    <span class=\"ty\">DynString</span> c = <span class=\"ty\">DynString</span>(<span class=\"str\">\"World\"</span>);  <span class=\"cm\">// move ctor (RHS is a temporary)</span>\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- explicit std::move ---\\n\"</span>;\n    <span class=\"ty\">DynString</span> d = <span class=\"fn\">std::move</span>(a);  <span class=\"cm\">// force move from lvalue; a is now empty</span>\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>--- copy from lvalue ---\n  ctor      \"Hello\"\n  copy ctor \"Hello\" (deep copy)\n--- move from rvalue ---\n  ctor      \"World\"\n  move ctor \"World\" (stole pointer)\n--- explicit std::move ---\n  move ctor \"Hello\" (stole pointer)\n  dtor      Hello\n  dtor      Hello\n  dtor      (moved-from)\n  dtor      World</code></pre></div></div><p class=\"l-text\"><strong>Why is move faster?</strong> A copy of a 1 GB buffer is 1 GB of <code>memcpy</code> plus a fresh allocation. A move is three pointer assignments — independent of the payload size. The classic micro-benchmark below builds a vector by repeatedly appending big strings, first with copy semantics and then with moves:</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> move_bench.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;chrono&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;vector&gt;</span>\n\n<span class=\"kw\">using</span> <span class=\"ty\">clk</span> = <span class=\"ty\">std::chrono::high_resolution_clock</span>;\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"kw\">const</span> <span class=\"ty\">int</span> N = <span class=\"num\">10000</span>;\n    <span class=\"ty\">std::string</span> big(<span class=\"num\">100000</span>, <span class=\"str\">'x'</span>);  <span class=\"cm\">// 100 KB string</span>\n\n    <span class=\"cm\">// COPY: each push_back duplicates the 100 KB buffer</span>\n    <span class=\"kw\">auto</span> t0 = <span class=\"ty\">clk</span>::<span class=\"fn\">now</span>();\n    <span class=\"ty\">std::vector&lt;std::string&gt;</span> v1;\n    <span class=\"kw\">for</span> (<span class=\"ty\">int</span> i = <span class=\"num\">0</span>; i &lt; N; ++i) v1.<span class=\"fn\">push_back</span>(big);            <span class=\"cm\">// COPY</span>\n    <span class=\"kw\">auto</span> t1 = <span class=\"ty\">clk</span>::<span class=\"fn\">now</span>();\n\n    <span class=\"cm\">// MOVE: each push_back transfers ownership; \"big\" gets rebuilt each round</span>\n    <span class=\"ty\">std::vector&lt;std::string&gt;</span> v2;\n    <span class=\"kw\">for</span> (<span class=\"ty\">int</span> i = <span class=\"num\">0</span>; i &lt; N; ++i) {\n        <span class=\"ty\">std::string</span> tmp(<span class=\"num\">100000</span>, <span class=\"str\">'x'</span>);\n        v2.<span class=\"fn\">push_back</span>(<span class=\"fn\">std::move</span>(tmp));                              <span class=\"cm\">// MOVE</span>\n    }\n    <span class=\"kw\">auto</span> t2 = <span class=\"ty\">clk</span>::<span class=\"fn\">now</span>();\n\n    <span class=\"kw\">using</span> ms = <span class=\"ty\">std::chrono::milliseconds</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"copy push_back: \"</span> &lt;&lt; <span class=\"ty\">std::chrono::duration_cast&lt;ms&gt;</span>(t1 - t0).<span class=\"fn\">count</span>() &lt;&lt; <span class=\"str\">\" ms\\n\"</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"move push_back: \"</span> &lt;&lt; <span class=\"ty\">std::chrono::duration_cast&lt;ms&gt;</span>(t2 - t1).<span class=\"fn\">count</span>() &lt;&lt; <span class=\"str\">\" ms\\n\"</span>;\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>copy push_back: 612 ms\nmove push_back: 18 ms</code></pre></div></div><div class=\"l-warn\"><strong>Important:</strong> after <code>std::move(x)</code>, <code>x</code> is in a <em>valid but unspecified</em> state. The destructor will still run, so you must leave the source in something safe to destroy (typically: pointers nulled, sizes zeroed). Do not <em>use</em> a moved-from object beyond reassigning or destroying it. Also: mark move constructors and move assignment <code>noexcept</code> — <code>std::vector</code> only uses moves during reallocation if they cannot throw; otherwise it falls back to copies for exception safety.</div><div class=\"l-highlight\"><strong>The Rule of Five</strong> — once you add move semantics, the Rule of Three grows by two. If your class manually manages a resource you must define <em>five</em> special member functions: (1) destructor, (2) copy constructor, (3) copy assignment, (4) move constructor, (5) move assignment. Declaring any of these disables the compiler-generated versions of the others, so be explicit.</div><div class=\"l-highlight\"><strong>The Rule of Zero</strong> — the best Rule of Five is the one you do not write. If every data member is itself an RAII type (<code>std::string</code>, <code>std::vector</code>, <code>std::unique_ptr</code>, <code>std::shared_ptr</code>...), the compiler-generated copy and move operations already do the right thing. Your class needs <em>none</em> of the five — that is the Rule of Zero.</div><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> rule_of_five_vs_zero.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;memory&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;vector&gt;</span>\n\n<span class=\"cm\">// === RULE OF FIVE: we manage a raw pointer ourselves ===</span>\n<span class=\"kw\">class</span> <span class=\"ty\">Buffer</span> {\n    <span class=\"ty\">int</span>* data_;\n    <span class=\"ty\">size_t</span> n_;\n<span class=\"kw\">public</span>:\n    <span class=\"ty\">Buffer</span>(<span class=\"ty\">size_t</span> n) : data_(<span class=\"kw\">new</span> <span class=\"ty\">int</span>[n]()), n_(n) {}\n    ~<span class=\"ty\">Buffer</span>()                                  { <span class=\"kw\">delete</span>[] data_; }                          <span class=\"cm\">// 1</span>\n    <span class=\"ty\">Buffer</span>(<span class=\"kw\">const</span> <span class=\"ty\">Buffer</span>&amp; o)                  : data_(<span class=\"kw\">new</span> <span class=\"ty\">int</span>[o.n_]), n_(o.n_) {     <span class=\"cm\">// 2</span>\n        <span class=\"kw\">for</span> (<span class=\"ty\">size_t</span> i = <span class=\"num\">0</span>; i &lt; n_; ++i) data_[i] = o.data_[i];\n    }\n    <span class=\"ty\">Buffer</span>&amp; <span class=\"kw\">operator</span>=(<span class=\"kw\">const</span> <span class=\"ty\">Buffer</span>&amp; o) {                                              <span class=\"cm\">// 3</span>\n        <span class=\"kw\">if</span> (<span class=\"kw\">this</span> != &amp;o) { <span class=\"ty\">Buffer</span> tmp(o); <span class=\"fn\">std::swap</span>(data_, tmp.data_); <span class=\"fn\">std::swap</span>(n_, tmp.n_); }\n        <span class=\"kw\">return</span> *<span class=\"kw\">this</span>;\n    }\n    <span class=\"ty\">Buffer</span>(<span class=\"ty\">Buffer</span>&amp;&amp; o) <span class=\"kw\">noexcept</span>             : data_(o.data_), n_(o.n_) {                <span class=\"cm\">// 4</span>\n        o.data_ = <span class=\"kw\">nullptr</span>; o.n_ = <span class=\"num\">0</span>;\n    }\n    <span class=\"ty\">Buffer</span>&amp; <span class=\"kw\">operator</span>=(<span class=\"ty\">Buffer</span>&amp;&amp; o) <span class=\"kw\">noexcept</span> {                                            <span class=\"cm\">// 5</span>\n        <span class=\"kw\">if</span> (<span class=\"kw\">this</span> != &amp;o) { <span class=\"kw\">delete</span>[] data_; data_ = o.data_; n_ = o.n_; o.data_ = <span class=\"kw\">nullptr</span>; o.n_ = <span class=\"num\">0</span>; }\n        <span class=\"kw\">return</span> *<span class=\"kw\">this</span>;\n    }\n};\n\n<span class=\"cm\">// === RULE OF ZERO: members are already RAII types ===</span>\n<span class=\"kw\">class</span> <span class=\"ty\">User</span> {\n    <span class=\"ty\">std::string</span> name_;\n    <span class=\"ty\">std::vector&lt;int&gt;</span> scores_;\n    <span class=\"ty\">std::unique_ptr&lt;<span class=\"ty\">Buffer</span>&gt;</span> buf_;\n<span class=\"kw\">public</span>:\n    <span class=\"ty\">User</span>(<span class=\"ty\">std::string</span> n) : name_(<span class=\"fn\">std::move</span>(n)), buf_(<span class=\"fn\">std::make_unique&lt;<span class=\"ty\">Buffer</span>&gt;</span>(<span class=\"num\">1024</span>)) {}\n    <span class=\"cm\">// No destructor, no copy/move ops written by hand —</span>\n    <span class=\"cm\">// the compiler-generated ones forward to string/vector/unique_ptr correctly.</span>\n};\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"ty\">User</span> u(<span class=\"str\">\"Mikail\"</span>);\n    <span class=\"ty\">User</span> v = <span class=\"fn\">std::move</span>(u);  <span class=\"cm\">// works: members are movable</span>\n    <span class=\"cm\">// User w = v;        // would fail to compile: unique_ptr is move-only</span>\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"User moved without writing a single special member.\\n\"</span>;\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>User moved without writing a single special member.</code></pre></div></div><div class=\"l-note\"><strong>Heuristic:</strong> aim for Rule of Zero. Reach for Rule of Five only when you really do own a raw resource that no standard type wraps. If you find yourself writing five special members for a class that holds a <code>std::vector</code>, you have probably gone wrong — let the vector do its job.</div><p class=\"l-text\"><strong>Stack vs heap allocation</strong> — every object lives somewhere. Two places matter:</p><ul class=\"l-list\"><li><strong>Stack</strong> — <code>T obj;</code> or <code>T obj(args);</code>. Lifetime is the enclosing scope (<code>{ ... }</code>). Allocation is essentially free (move the stack pointer). The destructor runs automatically when the scope ends. Size must be known at compile time and is limited (typically 1–8 MB total stack).</li><li><strong>Heap</strong> — <code>new T(args)</code> returns a pointer; you (or an owner) must <code>delete</code> it. Lifetime is whatever you make it — you can outlive the function that created it. Allocation cost is real (must find a free block). Size only limited by available memory.</li></ul><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> stack_vs_heap.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;memory&gt;</span>\n\n<span class=\"kw\">class</span> <span class=\"ty\">Widget</span> {\n    <span class=\"ty\">int</span> id_;\n<span class=\"kw\">public</span>:\n    <span class=\"ty\">Widget</span>(<span class=\"ty\">int</span> id) : id_(id) { <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  Widget(\"</span> &lt;&lt; id_ &lt;&lt; <span class=\"str\">\") born\\n\"</span>; }\n    ~<span class=\"ty\">Widget</span>()             { <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  Widget(\"</span> &lt;&lt; id_ &lt;&lt; <span class=\"str\">\") died\\n\"</span>; }\n};\n\n<span class=\"ty\">Widget</span>* <span class=\"fn\">leaky_factory</span>() {\n    <span class=\"kw\">return</span> <span class=\"kw\">new</span> <span class=\"ty\">Widget</span>(<span class=\"num\">2</span>);  <span class=\"cm\">// caller must remember to delete — easy to forget</span>\n}\n\n<span class=\"ty\">std::unique_ptr&lt;<span class=\"ty\">Widget</span>&gt;</span> <span class=\"fn\">safe_factory</span>() {\n    <span class=\"kw\">return</span> <span class=\"fn\">std::make_unique&lt;<span class=\"ty\">Widget</span>&gt;</span>(<span class=\"num\">3</span>);  <span class=\"cm\">// RAII owns the heap object</span>\n}\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- stack ---\\n\"</span>;\n    {\n        <span class=\"ty\">Widget</span> w(<span class=\"num\">1</span>);                      <span class=\"cm\">// on the stack</span>\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  using stack widget\\n\"</span>;\n    }                                   <span class=\"cm\">// destructor runs automatically here</span>\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- heap (raw new — LEAKS) ---\\n\"</span>;\n    <span class=\"ty\">Widget</span>* p = <span class=\"fn\">leaky_factory</span>();\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  using heap widget\\n\"</span>;\n    <span class=\"kw\">delete</span> p;                           <span class=\"cm\">// must remember; if we throw before this, we leak</span>\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- heap (unique_ptr — safe) ---\\n\"</span>;\n    <span class=\"kw\">auto</span> q = <span class=\"fn\">safe_factory</span>();             <span class=\"cm\">// RAII: dtor runs when q goes out of scope</span>\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  using owned heap widget\\n\"</span>;\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>--- stack ---\n  Widget(1) born\n  using stack widget\n  Widget(1) died\n--- heap (raw new — LEAKS) ---\n  Widget(2) born\n  using heap widget\n  Widget(2) died\n--- heap (unique_ptr — safe) ---\n  Widget(3) born\n  using owned heap widget\n  Widget(3) died</code></pre></div></div><div class=\"l-note\"><strong>When to pick which:</strong> default to the stack — it is fast, automatic, and exception-safe. Reach for the heap when (a) the object must outlive its creating scope, (b) it is too large for the stack, (c) its concrete type is decided at runtime (polymorphism via base pointer), or (d) its size is only known at runtime and varies. When you do go to the heap, never write a bare <code>new</code> — wrap it in <code>std::unique_ptr</code> or <code>std::shared_ptr</code> so RAII handles the cleanup for you. That single discipline eliminates almost every leak you would ever write.</div>",
tr: "<p class=\"l-text\">Nesne Yönelimli Programlama (NYP), kodu <strong>nesneler</strong> etrafında organize ettiğiniz bir paradigmadır — veri (nitelikler) ve bu veri üzerinde çalışan fonksiyonların (metotlar) bir araya getirilmesidir. C'deki gibi dağınık fonksiyonlar ve ayrı veri yapıları yerine, onları bir <strong>sınıf</strong> içinde birleştirirsiniz.</p><div class=\"lesson-outcomes\" style=\"background:rgba(200,169,110,0.06);border-left:3px solid #c8a96e;padding:1rem 1.2rem;margin:1.5rem 0;border-radius:0 8px 8px 0\"><div style=\"font-size:0.78rem;font-weight:700;letter-spacing:0.08em;color:#c8a96e;margin-bottom:0.6rem\">📍 BU DERSTE ÖĞRENECEKSİN</div><ul style=\"margin:0;padding-left:1.3rem;line-height:1.65;font-size:0.93rem;color:rgba(235,230,220,0.92)\"><li>Constructor, destructor ve access modifier ile sınıf tanımla</li><li>Kaynak ömrünü nesne ömrüne güvenle bağlamak için RAII uygula</li><li>Doğru değer semantiği için copy ve move constructor uygula</li><li>Kaynak sahipliğini yönetmek için rule of zero, three ve five uygula</li><li>Stack tahsisli ve heap tahsisli nesneleri ayır</li></ul></div><div class=\"l-highlight\"><strong>Neden NYP?</strong> C'de bir banka hesabını modelleyin: veri için bir <code>struct</code> (bakiye, sahip) ve struct'ı parametre olarak alan ayrı fonksiyonlar (<code>deposit()</code>, <code>withdraw()</code>) olurdu. Hiçbir şey birinin <code>account.balance</code>'ı negatif bir sayıya değiştirmesini engellemez. NYP bunu çözer: sınıf veriyi <strong>kapsüller</strong>, <code>balance</code>'ı private yapar ve yalnızca kuralları uygulayan kontrollü metotlarla değişikliğe izin verir (\"bakiye negatif olamaz\" gibi).</div><p class=\"l-text\"><strong>Prosedürel vs NYP</strong> — somut bir örnekle farkı görelim:</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> procedural_vs_oop.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string&gt;</span>\n\n<span class=\"cm\">// ===== PROSEDÜREL YAKLAŞIM =====</span>\n<span class=\"kw\">struct</span> <span class=\"ty\">AccountData</span> {\n    <span class=\"ty\">std::string</span> owner;\n    <span class=\"ty\">double</span> balance;\n};\n\n<span class=\"ty\">void</span> <span class=\"fn\">deposit_proc</span>(<span class=\"ty\">AccountData</span>&amp; acc, <span class=\"ty\">double</span> amount) {\n    acc.balance += amount;  <span class=\"cm\">// doğrulama yok!</span>\n}\n\n<span class=\"cm\">// ===== NYP YAKLAŞIMI =====</span>\n<span class=\"kw\">class</span> <span class=\"ty\">Account</span> {\n<span class=\"kw\">private</span>:\n    <span class=\"ty\">std::string</span> owner_;\n    <span class=\"ty\">double</span> balance_;\n\n<span class=\"kw\">public</span>:\n    <span class=\"ty\">Account</span>(<span class=\"kw\">const</span> <span class=\"ty\">std::string</span>&amp; owner, <span class=\"ty\">double</span> initial)\n        : owner_(owner), balance_(initial) {}\n\n    <span class=\"ty\">bool</span> <span class=\"fn\">deposit</span>(<span class=\"ty\">double</span> amount) {\n        <span class=\"kw\">if</span> (amount &lt;= <span class=\"num\">0</span>) <span class=\"kw\">return</span> <span class=\"kw\">false</span>;  <span class=\"cm\">// doğrulama!</span>\n        balance_ += amount;\n        <span class=\"kw\">return</span> <span class=\"kw\">true</span>;\n    }\n\n    <span class=\"ty\">double</span> <span class=\"fn\">get_balance</span>() <span class=\"kw\">const</span> { <span class=\"kw\">return</span> balance_; }\n    <span class=\"ty\">std::string</span> <span class=\"fn\">get_owner</span>() <span class=\"kw\">const</span> { <span class=\"kw\">return</span> owner_; }\n};\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"cm\">// Prosedürel: herkes değişmezleri bozabilir</span>\n    <span class=\"ty\">AccountData</span> a1 = {<span class=\"str\">\"Begüm\"</span>, <span class=\"num\">1000.0</span>};\n    a1.balance = <span class=\"num\">-999</span>;  <span class=\"cm\">// hay aksi! koruma yok</span>\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"Procedural: \"</span> &lt;&lt; a1.balance &lt;&lt; <span class=\"str\">'\\n'</span>;\n\n    <span class=\"cm\">// NYP: veri korunuyor</span>\n    <span class=\"ty\">Account</span> a2(<span class=\"str\">\"Mikail\"</span>, <span class=\"num\">1000.0</span>);\n    <span class=\"cm\">// a2.balance_ = -999;  // DERLEME HATASI: private!</span>\n    a2.<span class=\"fn\">deposit</span>(<span class=\"num\">500</span>);\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"OOP: \"</span> &lt;&lt; a2.<span class=\"fn\">get_owner</span>() &lt;&lt; <span class=\"str\">\" has $\"</span> &lt;&lt; a2.<span class=\"fn\">get_balance</span>() &lt;&lt; <span class=\"str\">'\\n'</span>;\n\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>Procedural: -999\nOOP: Mikail has $1500</code></pre></div></div><p class=\"l-text\"><strong>Erişim belirleyiciler</strong> kimin neye erişebileceğini kontrol eder:</p><ul class=\"l-list\"><li><code>private</code> — yalnızca sınıfın kendisi içinden erişilebilir. Sınıflar için varsayılandır. Doğrudan değiştirilmemesi gereken dahili durum için kullanın.</li><li><code>public</code> — her yerden erişilebilir. Arayüz için kullanın — kullanıcıların çağırmasını istediğiniz metotlar.</li><li><code>protected</code> — sınıf içinden ve türetilmiş sınıflarından (alt sınıflar) erişilebilir. Kalıtımın temel sınıf iç yapısına erişmesi gerektiğinde kullanın.</li></ul><p class=\"l-text\"><strong>Yapıcılar ve Yıkıcılar</strong> — Yapıcı, bir nesne oluşturulduğunda otomatik olarak çağrılan özel bir fonksiyondur. Nesnenin durumunu başlatır. Yıkıcı, nesne yok edildiğinde (kapsamdan çıktığında) otomatik olarak çağrılır. Bu <strong>RAII</strong>'nin temelidir: kaynakları yapıcıda edin, yıkıcıda serbest bırakın.</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> lifecycle.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string&gt;</span>\n\n<span class=\"kw\">class</span> <span class=\"ty\">Resource</span> {\n<span class=\"kw\">private</span>:\n    <span class=\"ty\">std::string</span> name_;\n\n<span class=\"kw\">public</span>:\n    <span class=\"cm\">// Varsayılan yapıcı</span>\n    <span class=\"ty\">Resource</span>() : name_(<span class=\"str\">\"unnamed\"</span>) {\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  Default constructor: \"</span> &lt;&lt; name_ &lt;&lt; <span class=\"str\">'\\n'</span>;\n    }\n\n    <span class=\"cm\">// Parametreli yapıcı</span>\n    <span class=\"ty\">Resource</span>(<span class=\"kw\">const</span> <span class=\"ty\">std::string</span>&amp; name) : name_(name) {\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  Parameterized constructor: \"</span> &lt;&lt; name_ &lt;&lt; <span class=\"str\">'\\n'</span>;\n    }\n\n    <span class=\"cm\">// Yıkıcı — nesne kapsamdan çıktığında otomatik çağrılır</span>\n    ~<span class=\"ty\">Resource</span>() {\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  Destructor: \"</span> &lt;&lt; name_ &lt;&lt; <span class=\"str\">'\\n'</span>;\n    }\n\n    <span class=\"ty\">std::string</span> <span class=\"fn\">name</span>() <span class=\"kw\">const</span> { <span class=\"kw\">return</span> name_; }\n};\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- Creating objects ---\\n\"</span>;\n    <span class=\"ty\">Resource</span> r1;               <span class=\"cm\">// varsayılan yapıcıyı çağırır</span>\n    <span class=\"ty\">Resource</span> r2(<span class=\"str\">\"FileHandle\"</span>);  <span class=\"cm\">// parametreli yapıcıyı çağırır</span>\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- Entering scope ---\\n\"</span>;\n    {\n        <span class=\"ty\">Resource</span> r3(<span class=\"str\">\"TempBuffer\"</span>);\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  Using \"</span> &lt;&lt; r3.<span class=\"fn\">name</span>() &lt;&lt; <span class=\"str\">'\\n'</span>;\n    }  <span class=\"cm\">// r3 burada yok ediliyor!</span>\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- Exiting main ---\\n\"</span>;\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}  <span class=\"cm\">// r2 yok edilir, sonra r1 (ters sıra!)</span></code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>--- Creating objects ---\n  Default constructor: unnamed\n  Parameterized constructor: FileHandle\n--- Entering scope ---\n  Parameterized constructor: TempBuffer\n  Using TempBuffer\n  Destructor: TempBuffer\n--- Exiting main ---\n  Destructor: FileHandle\n  Destructor: unnamed</code></pre></div></div><div class=\"l-note\"><strong>İpucu:</strong> Nesneler, oluşturma sırasının <strong>tersinde</strong> yok edilir. Bu, B nesnesi A nesnesine bağımlıysa (önce oluşturulan), B yok edilirken A'nın hala hayatta olmasını sağlar.</div><p class=\"l-text\"><strong>Üye başlatıcı listeleri</strong> — üyeleri her zaman yapıcı gövdesi içinde atama yerine başlatıcı listesinde (<code>:</code>'dan sonra) başlatmayı tercih edin. <code>const</code> üyeler, referanslar ve temel sınıflar için bu <strong>tek seçenektir</strong>. Diğer üyeler için daha verimlidir (varsayılan-oluşturma-sonra-atama yerine doğrudan başlatma).</p><p class=\"l-text\"><strong><code>this</code> işaretçisi</strong> — herhangi bir üye fonksiyon içinde, <code>this</code> mevcut nesneye bir işaretçidir. Ad belirsizliğini çözmek ve <strong>metot zincirleme</strong> için kullanışlıdır:</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> chaining.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string&gt;</span>\n\n<span class=\"kw\">class</span> <span class=\"ty\">QueryBuilder</span> {\n<span class=\"kw\">private</span>:\n    <span class=\"ty\">std::string</span> table_;\n    <span class=\"ty\">std::string</span> condition_;\n    <span class=\"ty\">int</span> limit_;\n\n<span class=\"kw\">public</span>:\n    <span class=\"ty\">QueryBuilder</span>() : limit_(<span class=\"num\">0</span>) {}\n\n    <span class=\"cm\">// Her metot zincirleme için *this döndürür</span>\n    <span class=\"ty\">QueryBuilder</span>&amp; <span class=\"fn\">from</span>(<span class=\"kw\">const</span> <span class=\"ty\">std::string</span>&amp; table) {\n        table_ = table;\n        <span class=\"kw\">return</span> *<span class=\"kw\">this</span>;\n    }\n    <span class=\"ty\">QueryBuilder</span>&amp; <span class=\"fn\">where</span>(<span class=\"kw\">const</span> <span class=\"ty\">std::string</span>&amp; cond) {\n        condition_ = cond;\n        <span class=\"kw\">return</span> *<span class=\"kw\">this</span>;\n    }\n    <span class=\"ty\">QueryBuilder</span>&amp; <span class=\"fn\">limit</span>(<span class=\"ty\">int</span> n) {\n        limit_ = n;\n        <span class=\"kw\">return</span> *<span class=\"kw\">this</span>;\n    }\n    <span class=\"ty\">std::string</span> <span class=\"fn\">build</span>() <span class=\"kw\">const</span> {\n        <span class=\"ty\">std::string</span> q = <span class=\"str\">\"SELECT * FROM \"</span> + table_;\n        <span class=\"kw\">if</span> (!condition_.<span class=\"fn\">empty</span>()) q += <span class=\"str\">\" WHERE \"</span> + condition_;\n        <span class=\"kw\">if</span> (limit_ &gt; <span class=\"num\">0</span>) q += <span class=\"str\">\" LIMIT \"</span> + <span class=\"fn\">std::to_string</span>(limit_);\n        <span class=\"kw\">return</span> q;\n    }\n};\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"ty\">std::string</span> query = <span class=\"ty\">QueryBuilder</span>()\n        .<span class=\"fn\">from</span>(<span class=\"str\">\"users\"</span>)\n        .<span class=\"fn\">where</span>(<span class=\"str\">\"age > 18\"</span>)\n        .<span class=\"fn\">limit</span>(<span class=\"num\">10</span>)\n        .<span class=\"fn\">build</span>();\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; query &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>SELECT * FROM users WHERE age > 18 LIMIT 10</code></pre></div></div><p class=\"l-text\"><strong>Operatör aşırı yükleme</strong> — C++, operatörlerin (<code>+</code>, <code>-</code>, <code>==</code>, <code>&lt;&lt;</code> vb.) özel türlerinizle nasıl çalışacağını tanımlamanıza izin verir. Bu, kullanıcı tanımlı türlerin yerleşik türler gibi hissettirmesini sağlar:</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> vec2.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;cmath&gt;</span>\n\n<span class=\"kw\">class</span> <span class=\"ty\">Vec2</span> {\n<span class=\"kw\">public</span>:\n    <span class=\"ty\">double</span> x, y;\n\n    <span class=\"ty\">Vec2</span>(<span class=\"ty\">double</span> x = <span class=\"num\">0</span>, <span class=\"ty\">double</span> y = <span class=\"num\">0</span>) : x(x), y(y) {}\n\n    <span class=\"cm\">// Aritmetik operatörler</span>\n    <span class=\"ty\">Vec2</span> <span class=\"kw\">operator</span>+(<span class=\"kw\">const</span> <span class=\"ty\">Vec2</span>&amp; o) <span class=\"kw\">const</span> { <span class=\"kw\">return</span> {x + o.x, y + o.y}; }\n    <span class=\"ty\">Vec2</span> <span class=\"kw\">operator</span>-(<span class=\"kw\">const</span> <span class=\"ty\">Vec2</span>&amp; o) <span class=\"kw\">const</span> { <span class=\"kw\">return</span> {x - o.x, y - o.y}; }\n    <span class=\"ty\">Vec2</span> <span class=\"kw\">operator</span>*(<span class=\"ty\">double</span> s)       <span class=\"kw\">const</span> { <span class=\"kw\">return</span> {x * s, y * s}; }\n\n    <span class=\"cm\">// Karşılaştırma</span>\n    <span class=\"ty\">bool</span> <span class=\"kw\">operator</span>==(<span class=\"kw\">const</span> <span class=\"ty\">Vec2</span>&amp; o) <span class=\"kw\">const</span> { <span class=\"kw\">return</span> x == o.x &amp;&amp; y == o.y; }\n\n    <span class=\"cm\">// Uzunluk</span>\n    <span class=\"ty\">double</span> <span class=\"fn\">length</span>() <span class=\"kw\">const</span> { <span class=\"kw\">return</span> <span class=\"fn\">std::sqrt</span>(x * x + y * y); }\n\n    <span class=\"cm\">// Akış çıkış operatörü (friend fonksiyon)</span>\n    <span class=\"kw\">friend</span> <span class=\"ty\">std::ostream</span>&amp; <span class=\"kw\">operator</span>&lt;&lt;(<span class=\"ty\">std::ostream</span>&amp; os, <span class=\"kw\">const</span> <span class=\"ty\">Vec2</span>&amp; v) {\n        os &lt;&lt; <span class=\"str\">\"(\"</span> &lt;&lt; v.x &lt;&lt; <span class=\"str\">\", \"</span> &lt;&lt; v.y &lt;&lt; <span class=\"str\">\")\"</span>;\n        <span class=\"kw\">return</span> os;\n    }\n};\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"ty\">Vec2</span> a(<span class=\"num\">3</span>, <span class=\"num\">4</span>), b(<span class=\"num\">1</span>, <span class=\"num\">2</span>);\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"a = \"</span> &lt;&lt; a &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"b = \"</span> &lt;&lt; b &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"a + b = \"</span> &lt;&lt; (a + b) &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"a - b = \"</span> &lt;&lt; (a - b) &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"a * 2 = \"</span> &lt;&lt; (a * <span class=\"num\">2</span>) &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"|a| = \"</span> &lt;&lt; a.<span class=\"fn\">length</span>() &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"a == b? \"</span> &lt;&lt; (a == b ? <span class=\"str\">\"yes\"</span> : <span class=\"str\">\"no\"</span>) &lt;&lt; <span class=\"str\">'\\n'</span>;\n\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>a = (3, 4)\nb = (1, 2)\na + b = (4, 6)\na - b = (2, 2)\na * 2 = (6, 8)\n|a| = 5\na == b? no</code></pre></div></div><div class=\"l-highlight\"><strong>Üç Kuralı</strong> — Sınıfınız bir kaynak yönetiyorsa (heap bellek, dosya tanıtıcısı, ağ soketi), üç şey tanımlamanız gerekir: (1) serbest bırakmak için bir <strong>yıkıcı</strong>, (2) derin kopya için bir <strong>kopya yapıcı</strong> ve (3) <code>a = b</code>'yi ele almak için bir <strong>kopya atama operatörü</strong>. Birini tanımlıyorsanız, neredeyse kesinlikle üçüne de ihtiyacınız vardır.</div><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> rule_of_three.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;cstring&gt;</span>\n\n<span class=\"kw\">class</span> <span class=\"ty\">DynString</span> {\n<span class=\"kw\">private</span>:\n    <span class=\"ty\">char</span>* data_;\n    <span class=\"ty\">size_t</span> len_;\n\n<span class=\"kw\">public</span>:\n    <span class=\"cm\">// Yapıcı</span>\n    <span class=\"ty\">DynString</span>(<span class=\"kw\">const</span> <span class=\"ty\">char</span>* s = <span class=\"str\">\"\"</span>) {\n        len_ = <span class=\"fn\">std::strlen</span>(s);\n        data_ = <span class=\"kw\">new</span> <span class=\"ty\">char</span>[len_ + <span class=\"num\">1</span>];\n        <span class=\"fn\">std::strcpy</span>(data_, s);\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  Construct: \\\"\"</span> &lt;&lt; data_ &lt;&lt; <span class=\"str\">\"\\\"\"</span> &lt;&lt; <span class=\"str\">'\\n'</span>;\n    }\n\n    <span class=\"cm\">// Yıkıcı</span>\n    ~<span class=\"ty\">DynString</span>() {\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  Destruct: \\\"\"</span> &lt;&lt; data_ &lt;&lt; <span class=\"str\">\"\\\"\"</span> &lt;&lt; <span class=\"str\">'\\n'</span>;\n        <span class=\"kw\">delete</span>[] data_;\n    }\n\n    <span class=\"cm\">// Kopya yapıcı (derin kopya)</span>\n    <span class=\"ty\">DynString</span>(<span class=\"kw\">const</span> <span class=\"ty\">DynString</span>&amp; other) {\n        len_ = other.len_;\n        data_ = <span class=\"kw\">new</span> <span class=\"ty\">char</span>[len_ + <span class=\"num\">1</span>];\n        <span class=\"fn\">std::strcpy</span>(data_, other.data_);\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  Copy: \\\"\"</span> &lt;&lt; data_ &lt;&lt; <span class=\"str\">\"\\\"\"</span> &lt;&lt; <span class=\"str\">'\\n'</span>;\n    }\n\n    <span class=\"cm\">// Kopya atama operatörü</span>\n    <span class=\"ty\">DynString</span>&amp; <span class=\"kw\">operator</span>=(<span class=\"kw\">const</span> <span class=\"ty\">DynString</span>&amp; other) {\n        <span class=\"kw\">if</span> (<span class=\"kw\">this</span> != &amp;other) {  <span class=\"cm\">// kendine atama kontrolü</span>\n            <span class=\"kw\">delete</span>[] data_;\n            len_ = other.len_;\n            data_ = <span class=\"kw\">new</span> <span class=\"ty\">char</span>[len_ + <span class=\"num\">1</span>];\n            <span class=\"fn\">std::strcpy</span>(data_, other.data_);\n            <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  Assign: \\\"\"</span> &lt;&lt; data_ &lt;&lt; <span class=\"str\">\"\\\"\"</span> &lt;&lt; <span class=\"str\">'\\n'</span>;\n        }\n        <span class=\"kw\">return</span> *<span class=\"kw\">this</span>;\n    }\n\n    <span class=\"kw\">const</span> <span class=\"ty\">char</span>* <span class=\"fn\">c_str</span>() <span class=\"kw\">const</span> { <span class=\"kw\">return</span> data_; }\n};\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- Construction ---\\n\"</span>;\n    <span class=\"ty\">DynString</span> s1(<span class=\"str\">\"Hello\"</span>);\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- Copy construction ---\\n\"</span>;\n    <span class=\"ty\">DynString</span> s2 = s1;  <span class=\"cm\">// kopya yapıcıyı çağırır</span>\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- Assignment ---\\n\"</span>;\n    <span class=\"ty\">DynString</span> s3(<span class=\"str\">\"World\"</span>);\n    s3 = s1;            <span class=\"cm\">// kopya atama operatörünü çağırır</span>\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- Destruction (reverse order) ---\\n\"</span>;\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>--- Construction ---\n  Construct: \"Hello\"\n--- Copy construction ---\n  Copy: \"Hello\"\n--- Assignment ---\n  Construct: \"World\"\n  Assign: \"Hello\"\n--- Destruction (reverse order) ---\n  Destruct: \"Hello\"\n  Destruct: \"Hello\"\n  Destruct: \"Hello\"</code></pre></div></div><div class=\"l-warn\"><strong>Uyarı:</strong> Düzgün bir kopya yapıcı olmadan, derleyici <strong>sığ kopya</strong> üretir — veriyi değil işaretçiyi kopyalar. Sonra her iki nesne de aynı belleğe işaret eder. İlki yok edildiğinde belleği serbest bırakır. İkinci nesne artık sarkmış bir işaretçiye sahiptir — serbest bırakılmış belleği kullanma, çift serbest bırakma, çökme.</div><p class=\"l-text\"><strong>Statik üyeler</strong> — herhangi bir belirli nesneye değil, sınıfın kendisine aittir. Bir <code>static</code> veri üyesi tüm örnekler arasında paylaşılır ve bir <code>static</code> metot nesne olmadan çağrılabilir:</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> static_demo.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n\n<span class=\"kw\">class</span> <span class=\"ty\">Entity</span> {\n<span class=\"kw\">private</span>:\n    <span class=\"kw\">static</span> <span class=\"ty\">int</span> count_;  <span class=\"cm\">// TÜM örnekler arasında paylaşılır</span>\n    <span class=\"ty\">int</span> id_;\n\n<span class=\"kw\">public</span>:\n    <span class=\"ty\">Entity</span>() : id_(++count_) {\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"Entity #\"</span> &lt;&lt; id_ &lt;&lt; <span class=\"str\">\" created (total: \"</span> &lt;&lt; count_ &lt;&lt; <span class=\"str\">\")\\n\"</span>;\n    }\n    ~<span class=\"ty\">Entity</span>() {\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"Entity #\"</span> &lt;&lt; id_ &lt;&lt; <span class=\"str\">\" destroyed\\n\"</span>;\n        --count_;\n    }\n    <span class=\"kw\">static</span> <span class=\"ty\">int</span> <span class=\"fn\">total</span>() { <span class=\"kw\">return</span> count_; }\n};\n\n<span class=\"ty\">int</span> <span class=\"ty\">Entity</span>::count_ = <span class=\"num\">0</span>;  <span class=\"cm\">// statik üyeyi sınıf dışında tanımla</span>\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"ty\">Entity</span> a, b;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"Total: \"</span> &lt;&lt; <span class=\"ty\">Entity</span>::<span class=\"fn\">total</span>() &lt;&lt; <span class=\"str\">'\\n'</span>;\n    {\n        <span class=\"ty\">Entity</span> c;\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"Total: \"</span> &lt;&lt; <span class=\"ty\">Entity</span>::<span class=\"fn\">total</span>() &lt;&lt; <span class=\"str\">'\\n'</span>;\n    }\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"Total: \"</span> &lt;&lt; <span class=\"ty\">Entity</span>::<span class=\"fn\">total</span>() &lt;&lt; <span class=\"str\">'\\n'</span>;\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>Entity #1 created (total: 1)\nEntity #2 created (total: 2)\nTotal: 2\nEntity #3 created (total: 3)\nTotal: 3\nEntity #3 destroyed\nTotal: 2\nEntity #2 destroyed\nEntity #1 destroyed</code></pre></div></div><p class=\"l-text\"><strong>Taşıma Yapıcısı (C++11)</strong> — kaynak nesne zaten yok olmak üzereyken kopyalamak pahalıdır. Bir <code>DynString</code> döndüren fonksiyon ya da büyümesi gereken bir vektör için, eski nesneden işaretçiyi sadece <em>çalmak</em> varken neden yeni bir tampon ayırıp baytları memcpy edelim? İşte <strong>taşıma yapıcısının</strong> işi budur. Bir <code>rvalue referansı</code> (<code>T&amp;&amp;</code>) alır — sadece geçicilere (ya da <code>std::move</code> ile açıkça işaretlediğiniz şeylere) bağlanan bir referans — ve içeriklerin sahipliğini devreder.</p><div class=\"l-highlight\"><strong>Bir dakikada rvalue referansları.</strong> Bir <em>lvalue</em>, adı ve adresini alabileceğiniz bir şeydir (<code>int x; x = 5;</code>). Bir <em>rvalue</em> ise geçicidir: <code>x + 1</code>'in sonucu ya da bir fonksiyon dönüş değeri gibi. <code>T&amp;</code> lvalue'lara, <code>const T&amp;</code> ikisine birden bağlanır. <code>T&amp;&amp;</code> ise yalnızca rvalue'lara bağlanır — yani kaynağın az sonra yok edileceğini bildiğiniz için içini boşaltmak güvenlidir.</div><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> move_ctor.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;cstring&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;utility&gt;</span>  <span class=\"cm\">// std::move</span>\n\n<span class=\"kw\">class</span> <span class=\"ty\">DynString</span> {\n<span class=\"kw\">private</span>:\n    <span class=\"ty\">char</span>* data_;\n    <span class=\"ty\">size_t</span> len_;\n\n<span class=\"kw\">public</span>:\n    <span class=\"ty\">DynString</span>(<span class=\"kw\">const</span> <span class=\"ty\">char</span>* s = <span class=\"str\">\"\"</span>) : len_(<span class=\"fn\">std::strlen</span>(s)) {\n        data_ = <span class=\"kw\">new</span> <span class=\"ty\">char</span>[len_ + <span class=\"num\">1</span>];\n        <span class=\"fn\">std::strcpy</span>(data_, s);\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  ctor      \\\"\"</span> &lt;&lt; data_ &lt;&lt; <span class=\"str\">\"\\\"\\n\"</span>;\n    }\n    ~<span class=\"ty\">DynString</span>() {\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  dtor      \"</span> &lt;&lt; (data_ ? data_ : <span class=\"str\">\"(moved-from)\"</span>) &lt;&lt; <span class=\"str\">'\\n'</span>;\n        <span class=\"kw\">delete</span>[] data_;\n    }\n\n    <span class=\"cm\">// Kopya yapıcı — bellek ayırır ve baytları kopyalar (pahalı)</span>\n    <span class=\"ty\">DynString</span>(<span class=\"kw\">const</span> <span class=\"ty\">DynString</span>&amp; other) : len_(other.len_) {\n        data_ = <span class=\"kw\">new</span> <span class=\"ty\">char</span>[len_ + <span class=\"num\">1</span>];\n        <span class=\"fn\">std::strcpy</span>(data_, other.data_);\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  copy ctor \\\"\"</span> &lt;&lt; data_ &lt;&lt; <span class=\"str\">\"\\\" (deep copy)\\n\"</span>;\n    }\n\n    <span class=\"cm\">// Taşıma yapıcısı — işaretçiyi çalar (ucuz, O(1))</span>\n    <span class=\"ty\">DynString</span>(<span class=\"ty\">DynString</span>&amp;&amp; other) <span class=\"kw\">noexcept</span>\n        : data_(other.data_), len_(other.len_) {\n        other.data_ = <span class=\"kw\">nullptr</span>;  <span class=\"cm\">// kaynağı geçerli, yok edilebilir bir durumda bırak</span>\n        other.len_  = <span class=\"num\">0</span>;\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  move ctor \\\"\"</span> &lt;&lt; data_ &lt;&lt; <span class=\"str\">\"\\\" (stole pointer)\\n\"</span>;\n    }\n\n    <span class=\"cm\">// Taşıma ataması — bizimkini bırak, onlarınkini çal</span>\n    <span class=\"ty\">DynString</span>&amp; <span class=\"kw\">operator</span>=(<span class=\"ty\">DynString</span>&amp;&amp; other) <span class=\"kw\">noexcept</span> {\n        <span class=\"kw\">if</span> (<span class=\"kw\">this</span> != &amp;other) {\n            <span class=\"kw\">delete</span>[] data_;\n            data_ = other.data_;\n            len_  = other.len_;\n            other.data_ = <span class=\"kw\">nullptr</span>;\n            other.len_  = <span class=\"num\">0</span>;\n            <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  move=     (stole pointer)\\n\"</span>;\n        }\n        <span class=\"kw\">return</span> *<span class=\"kw\">this</span>;\n    }\n};\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- copy from lvalue ---\\n\"</span>;\n    <span class=\"ty\">DynString</span> a(<span class=\"str\">\"Hello\"</span>);\n    <span class=\"ty\">DynString</span> b = a;             <span class=\"cm\">// kopya yapıcı (a bir lvalue)</span>\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- move from rvalue ---\\n\"</span>;\n    <span class=\"ty\">DynString</span> c = <span class=\"ty\">DynString</span>(<span class=\"str\">\"World\"</span>);  <span class=\"cm\">// taşıma yapıcısı (sağ taraf geçici)</span>\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- explicit std::move ---\\n\"</span>;\n    <span class=\"ty\">DynString</span> d = <span class=\"fn\">std::move</span>(a);  <span class=\"cm\">// lvalue'dan zorla taşı; a artık boş</span>\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>--- copy from lvalue ---\n  ctor      \"Hello\"\n  copy ctor \"Hello\" (deep copy)\n--- move from rvalue ---\n  ctor      \"World\"\n  move ctor \"World\" (stole pointer)\n--- explicit std::move ---\n  move ctor \"Hello\" (stole pointer)\n  dtor      Hello\n  dtor      Hello\n  dtor      (moved-from)\n  dtor      World</code></pre></div></div><p class=\"l-text\"><strong>Taşıma neden daha hızlı?</strong> 1 GB tamponun kopyası 1 GB <code>memcpy</code> artı taze bir bellek ayırmadır. Taşıma ise üç işaretçi atamasıdır — yük boyutundan bağımsız. Aşağıdaki klasik mikro-benchmark, büyük dizgeleri tekrar tekrar ekleyerek bir vektör inşa eder; önce kopya semantiğiyle, sonra taşımayla:</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> move_bench.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;chrono&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;vector&gt;</span>\n\n<span class=\"kw\">using</span> <span class=\"ty\">clk</span> = <span class=\"ty\">std::chrono::high_resolution_clock</span>;\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"kw\">const</span> <span class=\"ty\">int</span> N = <span class=\"num\">10000</span>;\n    <span class=\"ty\">std::string</span> big(<span class=\"num\">100000</span>, <span class=\"str\">'x'</span>);  <span class=\"cm\">// 100 KB dizge</span>\n\n    <span class=\"cm\">// KOPYA: her push_back 100 KB tamponu çoğaltır</span>\n    <span class=\"kw\">auto</span> t0 = <span class=\"ty\">clk</span>::<span class=\"fn\">now</span>();\n    <span class=\"ty\">std::vector&lt;std::string&gt;</span> v1;\n    <span class=\"kw\">for</span> (<span class=\"ty\">int</span> i = <span class=\"num\">0</span>; i &lt; N; ++i) v1.<span class=\"fn\">push_back</span>(big);            <span class=\"cm\">// KOPYA</span>\n    <span class=\"kw\">auto</span> t1 = <span class=\"ty\">clk</span>::<span class=\"fn\">now</span>();\n\n    <span class=\"cm\">// TAŞIMA: her push_back sahipliği aktarır; \"big\" her turda yeniden inşa edilir</span>\n    <span class=\"ty\">std::vector&lt;std::string&gt;</span> v2;\n    <span class=\"kw\">for</span> (<span class=\"ty\">int</span> i = <span class=\"num\">0</span>; i &lt; N; ++i) {\n        <span class=\"ty\">std::string</span> tmp(<span class=\"num\">100000</span>, <span class=\"str\">'x'</span>);\n        v2.<span class=\"fn\">push_back</span>(<span class=\"fn\">std::move</span>(tmp));                              <span class=\"cm\">// TAŞIMA</span>\n    }\n    <span class=\"kw\">auto</span> t2 = <span class=\"ty\">clk</span>::<span class=\"fn\">now</span>();\n\n    <span class=\"kw\">using</span> ms = <span class=\"ty\">std::chrono::milliseconds</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"copy push_back: \"</span> &lt;&lt; <span class=\"ty\">std::chrono::duration_cast&lt;ms&gt;</span>(t1 - t0).<span class=\"fn\">count</span>() &lt;&lt; <span class=\"str\">\" ms\\n\"</span>;\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"move push_back: \"</span> &lt;&lt; <span class=\"ty\">std::chrono::duration_cast&lt;ms&gt;</span>(t2 - t1).<span class=\"fn\">count</span>() &lt;&lt; <span class=\"str\">\" ms\\n\"</span>;\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>copy push_back: 612 ms\nmove push_back: 18 ms</code></pre></div></div><div class=\"l-warn\"><strong>Önemli:</strong> <code>std::move(x)</code>'ten sonra <code>x</code>, <em>geçerli ama belirsiz</em> bir durumdadır. Yıkıcı yine çalışacaktır, bu yüzden kaynağı yok edilmesi güvenli bir şeyde bırakmalısınız (tipik olarak: işaretçiler null'lanmış, boyutlar sıfırlanmış). Taşınmış-bir-nesneyi yeniden atamak ya da yok etmek dışında <em>kullanmayın</em>. Ayrıca: taşıma yapıcılarını ve taşıma atamasını <code>noexcept</code> olarak işaretleyin — <code>std::vector</code> yeniden bellek ayırma sırasında taşımaları yalnızca istisna atmazlarsa kullanır; aksi takdirde istisna güvenliği için kopyalara geri döner.</div><div class=\"l-highlight\"><strong>Beş Kuralı (Rule of Five)</strong> — taşıma semantiği eklediğinizde, Üç Kuralı ikiye büyür. Sınıfınız bir kaynağı elle yönetiyorsa <em>beş</em> özel üye işlevi tanımlamalısınız: (1) yıkıcı, (2) kopya yapıcı, (3) kopya ataması, (4) taşıma yapıcısı, (5) taşıma ataması. Bunlardan herhangi birini bildirmek diğerlerinin derleyici tarafından üretilmiş sürümlerini devre dışı bırakır; o yüzden açık olun.</div><div class=\"l-highlight\"><strong>Sıfır Kuralı (Rule of Zero)</strong> — en iyi Beş Kuralı, yazmadığınız Beş Kuralıdır. Her veri üyesi kendisi bir RAII tipi ise (<code>std::string</code>, <code>std::vector</code>, <code>std::unique_ptr</code>, <code>std::shared_ptr</code>...), derleyici tarafından üretilen kopya ve taşıma işlemleri zaten doğru olanı yapar. Sınıfınızın beşten <em>hiçbirine</em> ihtiyacı yoktur — işte Sıfır Kuralı.</div><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> rule_of_five_vs_zero.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;memory&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;vector&gt;</span>\n\n<span class=\"cm\">// === BEŞ KURALI: ham bir işaretçiyi kendimiz yönetiyoruz ===</span>\n<span class=\"kw\">class</span> <span class=\"ty\">Buffer</span> {\n    <span class=\"ty\">int</span>* data_;\n    <span class=\"ty\">size_t</span> n_;\n<span class=\"kw\">public</span>:\n    <span class=\"ty\">Buffer</span>(<span class=\"ty\">size_t</span> n) : data_(<span class=\"kw\">new</span> <span class=\"ty\">int</span>[n]()), n_(n) {}\n    ~<span class=\"ty\">Buffer</span>()                                  { <span class=\"kw\">delete</span>[] data_; }                          <span class=\"cm\">// 1</span>\n    <span class=\"ty\">Buffer</span>(<span class=\"kw\">const</span> <span class=\"ty\">Buffer</span>&amp; o)                  : data_(<span class=\"kw\">new</span> <span class=\"ty\">int</span>[o.n_]), n_(o.n_) {     <span class=\"cm\">// 2</span>\n        <span class=\"kw\">for</span> (<span class=\"ty\">size_t</span> i = <span class=\"num\">0</span>; i &lt; n_; ++i) data_[i] = o.data_[i];\n    }\n    <span class=\"ty\">Buffer</span>&amp; <span class=\"kw\">operator</span>=(<span class=\"kw\">const</span> <span class=\"ty\">Buffer</span>&amp; o) {                                              <span class=\"cm\">// 3</span>\n        <span class=\"kw\">if</span> (<span class=\"kw\">this</span> != &amp;o) { <span class=\"ty\">Buffer</span> tmp(o); <span class=\"fn\">std::swap</span>(data_, tmp.data_); <span class=\"fn\">std::swap</span>(n_, tmp.n_); }\n        <span class=\"kw\">return</span> *<span class=\"kw\">this</span>;\n    }\n    <span class=\"ty\">Buffer</span>(<span class=\"ty\">Buffer</span>&amp;&amp; o) <span class=\"kw\">noexcept</span>             : data_(o.data_), n_(o.n_) {                <span class=\"cm\">// 4</span>\n        o.data_ = <span class=\"kw\">nullptr</span>; o.n_ = <span class=\"num\">0</span>;\n    }\n    <span class=\"ty\">Buffer</span>&amp; <span class=\"kw\">operator</span>=(<span class=\"ty\">Buffer</span>&amp;&amp; o) <span class=\"kw\">noexcept</span> {                                            <span class=\"cm\">// 5</span>\n        <span class=\"kw\">if</span> (<span class=\"kw\">this</span> != &amp;o) { <span class=\"kw\">delete</span>[] data_; data_ = o.data_; n_ = o.n_; o.data_ = <span class=\"kw\">nullptr</span>; o.n_ = <span class=\"num\">0</span>; }\n        <span class=\"kw\">return</span> *<span class=\"kw\">this</span>;\n    }\n};\n\n<span class=\"cm\">// === SIFIR KURALI: üyeler zaten RAII tipleri ===</span>\n<span class=\"kw\">class</span> <span class=\"ty\">User</span> {\n    <span class=\"ty\">std::string</span> name_;\n    <span class=\"ty\">std::vector&lt;int&gt;</span> scores_;\n    <span class=\"ty\">std::unique_ptr&lt;<span class=\"ty\">Buffer</span>&gt;</span> buf_;\n<span class=\"kw\">public</span>:\n    <span class=\"ty\">User</span>(<span class=\"ty\">std::string</span> n) : name_(<span class=\"fn\">std::move</span>(n)), buf_(<span class=\"fn\">std::make_unique&lt;<span class=\"ty\">Buffer</span>&gt;</span>(<span class=\"num\">1024</span>)) {}\n    <span class=\"cm\">// Yıkıcı yok, elle yazılmış kopya/taşıma işlemi yok —</span>\n    <span class=\"cm\">// derleyici-üretimi olanlar string/vector/unique_ptr'a doğru şekilde iletir.</span>\n};\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"ty\">User</span> u(<span class=\"str\">\"Mikail\"</span>);\n    <span class=\"ty\">User</span> v = <span class=\"fn\">std::move</span>(u);  <span class=\"cm\">// çalışır: üyeler taşınabilir</span>\n    <span class=\"cm\">// User w = v;        // derlenmez: unique_ptr yalnızca taşınabilir</span>\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"User moved without writing a single special member.\\n\"</span>;\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>User moved without writing a single special member.</code></pre></div></div><div class=\"l-note\"><strong>Pratik kural:</strong> Sıfır Kuralını hedefleyin. Beş Kuralına yalnızca, hiçbir standart tipin sarmadığı ham bir kaynağa gerçekten sahipseniz uzanın. Bir <code>std::vector</code> tutan bir sınıf için beş özel üye yazıyor bulursanız kendinizi, muhtemelen yanlış yoldasınızdır — bırakın vektör işini yapsın.</div><p class=\"l-text\"><strong>Yığın ve heap üzerinde tahsis</strong> — her nesne bir yerde yaşar. İki yer önemlidir:</p><ul class=\"l-list\"><li><strong>Yığın (Stack)</strong> — <code>T obj;</code> ya da <code>T obj(args);</code>. Yaşam süresi, içine alınan kapsamdır (<code>{ ... }</code>). Tahsis pratikte bedavadır (yığın işaretçisini kaydırırsın). Kapsam bittiğinde yıkıcı otomatik çalışır. Boyut derleme zamanında bilinmek zorundadır ve sınırlıdır (tipik olarak toplam 1–8 MB yığın).</li><li><strong>Heap (Öbek)</strong> — <code>new T(args)</code> bir işaretçi döndürür; siz (ya da bir sahip) onu <code>delete</code> etmelisiniz. Yaşam süresi siz ne istersiniz odur — kendisini yaratan fonksiyonu aşıp yaşayabilir. Tahsis maliyeti gerçektir (boş bir blok bulmak gerekir). Boyut yalnızca mevcut bellekle sınırlıdır.</li></ul><div class=\"code-wrap\"><div class=\"code-label\"><span>C++</span> stack_vs_heap.cpp <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;iostream&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;memory&gt;</span>\n\n<span class=\"kw\">class</span> <span class=\"ty\">Widget</span> {\n    <span class=\"ty\">int</span> id_;\n<span class=\"kw\">public</span>:\n    <span class=\"ty\">Widget</span>(<span class=\"ty\">int</span> id) : id_(id) { <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  Widget(\"</span> &lt;&lt; id_ &lt;&lt; <span class=\"str\">\") born\\n\"</span>; }\n    ~<span class=\"ty\">Widget</span>()             { <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  Widget(\"</span> &lt;&lt; id_ &lt;&lt; <span class=\"str\">\") died\\n\"</span>; }\n};\n\n<span class=\"ty\">Widget</span>* <span class=\"fn\">leaky_factory</span>() {\n    <span class=\"kw\">return</span> <span class=\"kw\">new</span> <span class=\"ty\">Widget</span>(<span class=\"num\">2</span>);  <span class=\"cm\">// çağıran delete'i hatırlamak zorunda — unutulması kolay</span>\n}\n\n<span class=\"ty\">std::unique_ptr&lt;<span class=\"ty\">Widget</span>&gt;</span> <span class=\"fn\">safe_factory</span>() {\n    <span class=\"kw\">return</span> <span class=\"fn\">std::make_unique&lt;<span class=\"ty\">Widget</span>&gt;</span>(<span class=\"num\">3</span>);  <span class=\"cm\">// RAII heap nesnesinin sahibidir</span>\n}\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>() {\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- stack ---\\n\"</span>;\n    {\n        <span class=\"ty\">Widget</span> w(<span class=\"num\">1</span>);                      <span class=\"cm\">// yığın üzerinde</span>\n        <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  using stack widget\\n\"</span>;\n    }                                   <span class=\"cm\">// yıkıcı burada otomatik çalışır</span>\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- heap (raw new — LEAKS) ---\\n\"</span>;\n    <span class=\"ty\">Widget</span>* p = <span class=\"fn\">leaky_factory</span>();\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  using heap widget\\n\"</span>;\n    <span class=\"kw\">delete</span> p;                           <span class=\"cm\">// hatırlamak şart; öncesinde throw edersek sızıntı olur</span>\n\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"--- heap (unique_ptr — safe) ---\\n\"</span>;\n    <span class=\"kw\">auto</span> q = <span class=\"fn\">safe_factory</span>();             <span class=\"cm\">// RAII: q kapsamdan çıkınca yıkıcı çalışır</span>\n    <span class=\"fn\">std::cout</span> &lt;&lt; <span class=\"str\">\"  using owned heap widget\\n\"</span>;\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>--- stack ---\n  Widget(1) born\n  using stack widget\n  Widget(1) died\n--- heap (raw new — LEAKS) ---\n  Widget(2) born\n  using heap widget\n  Widget(2) died\n--- heap (unique_ptr — safe) ---\n  Widget(3) born\n  using owned heap widget\n  Widget(3) died</code></pre></div></div><div class=\"l-note\"><strong>Hangisini ne zaman seçmeli:</strong> öntanımlı olarak yığını seçin — hızlı, otomatik ve istisna-güvenlidir. Heap'e şu durumlarda uzanın: (a) nesnenin kendisini yaratan kapsamı aşıp yaşaması gerekiyorsa, (b) yığın için fazla büyükse, (c) somut tipi çalışma zamanında belirleniyorsa (taban işaretçi üzerinden çok biçimlilik), ya da (d) boyutu yalnızca çalışma zamanında biliniyor ve değişiyorsa. Heap'e gittiğinizde, asla çıplak <code>new</code> yazmayın — onu <code>std::unique_ptr</code> ya da <code>std::shared_ptr</code> içine sarın ki RAII temizliği sizin yerinize halletsin. Bu tek disiplin, yazabileceğiniz neredeyse her sızıntıyı ortadan kaldırır.</div>"
};
